/// <summary>
/// AVA_007513_TransferJournalsDepreciation
/// </summary>
[
    DataContractAttribute,
    SysOperationGroupAttribute('GrCode', '@AssetLeasing:DateInterval', '1'),
    SysOperationGroupAttribute('GrDate', ' ', '2'),
    SysOperationGroupAttribute('GrOther', '@SYS1436', '3'),
    SysOperationContractProcessingAttribute(classStr(AVATransferCalcDepreciationUIBuilder), SysOperationDataContractProcessingMode::CreateUIBuilderForRootContractOnly)
]

public class AVATransferCalcDepreciationContract implements SysOperationValidatable
{
    DateCode            dateCode;
    FromDate            fromDate;
    ToDate              toDate;
    LedgerJournalNameId journalName;
    TransDate           postingDate;

}

Method.Source:
[
    DataMemberAttribute('DateCode'),
    SysOperationLabelAttribute(literalStr("@AssetLeasing:DateInterval")),
    SysOperationGroupMemberAttribute('GrCode'),
    SysOperationDisplayOrderAttribute('1')
]
public DateCode parmPeriodCode(DateCode _dateCode = dateCode)
{
    dateCode = _dateCode;
    return dateCode;
}

[
DataMemberAttribute('FromDate'),
SysOperationLabelAttribute(literalStr("@AssetLeasing:AssetLeaseFromDate")),
SysOperationGroupMemberAttribute('GrCode'),
SysOperationDisplayOrderAttribute('2')
]
public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

[
    DataMemberAttribute('ToDate'),
    SysOperationLabelAttribute(literalstr("@SYS345091")),
    SysOperationGroupMemberAttribute('GrCode'),
    SysOperationDisplayOrderAttribute('3')
]
public ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;
    return toDate;
}

[
    DataMemberAttribute('LedgerJournalNameId'),
    SysOperationLabelAttribute(literalstr("@NDX:NXACalcDepreciationJournal")),
    SysOperationGroupMemberAttribute('GrOther'),
    SysOperationDisplayOrderAttribute('1')
]
public LedgerJournalNameId parmJournalName(LedgerJournalNameId  _journal = journalName)
{
    journalName = _journal;
    return journalName;
}

[
    DataMemberAttribute('PostingDate'),
    SysOperationLabelAttribute(literalstr("@NDX:NXAPostingDate")),
    SysOperationGroupMemberAttribute('GrOther'),
    SysOperationDisplayOrderAttribute('2')
]
    public TransDate parmPostingDate(TransDate  _postingDate = postingDate)
{
    postingDate = _postingDate;
    return postingDate;
}

public boolean validate()
{
    boolean isValid = true;
    if (!fromDate)
    {
        isValid = checkFailed(strFmt("@SYS84753", "@AssetLeasing:AssetLeaseFromDate"));
    }
    if (!toDate)
    {
        isValid = checkFailed(strFmt("@SYS84753", "@SYS345091"));
    }
    if (fromDate > toDate)
    {
        isValid = checkFailed("@SYS300457");
    }
    if (!postingDate)
    {
        isValid = checkFailed(strFmt("@SYS84753", "@NDX:NXAPostingDate"));
    }

    return isValid;
}
